20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(TelephoneE164.normalizeOrNull(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(request.getTelephone());
23	            }
24	        }
25	    }
